{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Using a managed policy with wildcard permissions",
      "resource": "aws_iam_policy_attachment.pass4",
      "severity": "HIGH",
      "explanation": "The 'AmazonS3ReadOnlyAccess' policy attached to 'aws_iam_role.pass1' via 'aws_iam_policy_attachment.pass4' allows read access to all S3 buckets, potentially exposing sensitive data."
    }
  ],
  "patched_code": "resource "aws_iam_policy_attachment" "pass4" {
  name       = "policy"
  role       = aws_iam_role.pass1.name
  policy_arn = aws_iam_policy.pass4_policy.arn
}

resource "aws_iam_policy" "pass4_policy" {
  name        = "S3ReadOnlyAccessLimited"
  description = "Limited S3 read-only access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:Get*",
          "s3:List*"
        ]
        Resource = [
          "arn:aws:s3:::my-specific-bucket",
          "arn:aws:s3:::my-specific-bucket/*"
        ]
      }
    ]
  })
}",
  "fix_summary": "Replaced the 'AmazonS3ReadOnlyAccess' managed policy with a custom IAM policy 'S3ReadOnlyAccessLimited' that grants read-only access to a specific S3 bucket instead of all buckets."
}
